head.script:
// 테스트 설명, 유효성 값 설정
//  [분리 사유] @spec2(RowNum, RowStatus Header 속성 설정 불가) 와 @spec3(Body MultiLine) 은
//   검증에 필요한 GridView 구성이 서로 다르다.
//    - @spec2 : RowNum / RowStatus Column 을 표시한 단일 Line 그리드 (_3 소유)
//    - @spec3 : Body 가 2 Line 으로 나뉜 MultiLine 그리드 (본 샘플 소유)
//   한 샘플에 두 구성을 함께 두면 전제가 섞여 관찰 대상이 모호해지므로 _3 / _4 로 분리한다.
//  [소유 범위] 본 샘플은 @spec3 만 검증한다.
//   기본 propval(true / false) 과 'Header Column 에서만 동작' 은 _1,
//   headerFilter / useFilterList / showSortableUseFilter 상호작용은 _2 가 소유하므로 여기서 중복 검증하지 않는다.
scwin.tData = {
    "description" : "[column > P > useFilter]<br/>GridView 컴포넌트의 Header Column 에 CustomFilter 기능을 활성화할지 설정합니다.",
    "validation" : [
        "Body Column 이 MultiLine 이어도 동일 Column Line 에 필터가 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 필터 적용 결과 확인 :
//  사용자가 2줄 Header Column(담당지점) 의 필터 버튼으로 조건을 적용한 뒤 이 버튼을 누르면
//  현재 표시 중인 Row 의 1줄 Column(지역, Column 인덱스 0) 과 2줄 Column(담당지점, Column 인덱스 2) 값을 대비 출력한다.
//  (MultiLine 이어도 Column 인덱스는 Line 에 걸쳐 전역으로 이어지므로 셀 id 는 target1_cell_{Row}_{전역 Column 인덱스})
//  필터로 제외된 Row 는 DOM 에 남아있고 숨김 처리만 되므로, 표시 대상은 getDataLength() 로 한정한다.
//  필터 조작 자체는 사용자 액션이므로 별도 트리거 버튼을 만들지 않는다.
scwin.btn_checkFilterResult_onclick = function () {
    let scb = wf_body_bottom.getObj("scwin");
    scb.btn_clear_onclick();

    let cnt = target1.getDataLength();
    scb.setReturnValue("표시 중인 Row 수 : " + cnt);

    for (let r = 0; r < cnt; r++) {
        let cell0 = document.querySelector("td[id$='target1_cell_" + r + "_0']");
        let cell2 = document.querySelector("td[id$='target1_cell_" + r + "_2']");
        scb.setReturnValue("Row " + r + " -> 1줄 지역(Column 0) : " + (cell0 ? cell0.textContent.trim() : "") + " / 2줄 담당지점(Column 2) : " + (cell2 ? cell2.textContent.trim() : ""));
    }
}
